insert into public.settings (key, value) values
  ($q$company$q$, $q${"name":"Qadam","tagline":"недвижимость и оценка","slogan":"Купить, продать, сдать и оценить — в одном окне","legal_name":"ТОО «Название компании» — укажите в настройках","bin":"","about":"Агентство полного цикла: подбор и продажа жилья, аренда, коммерческая недвижимость, юридическая проверка и сопровождение сделок, ипотечный брокер и независимая оценка движимого и недвижимого имущества. Работаем по договору, комиссию фиксируем письменно до начала работы.","appraiser_note":"Отчёты об оценке подписывают оценщики с квалификационным свидетельством, состоящие в палате оценщиков (Закон РК от 10.01.2018 № 133-VI «Об оценочной деятельности в Республике Казахстан»)."}$q$::jsonb),
  ($q$contacts$q$, $q${"phone":"+7 (700) 000-00-00","whatsapp":"77000000000","telegram":"","instagram":"","email":"info@example.kz","city":"Астана","address":"Адрес офиса — укажите в админке → Настройки","hours":"Пн–Пт 9:00–19:00, Сб 10:00–16:00","lat":51.1282,"lng":71.4306,"two_gis_url":""}$q$::jsonb),
  ($q$finance$q$, $q${"year":2026,"mrp":4325,"ipn_rate":10,"ipn_rate_high":15,"ipn_threshold_mrp":8500,"gov_fee_apartment":1304,"fast_registration":5000,"con_contract":8500,"notary_mrp_nonrel":12,"notary_mrp_rel":7,"notary_mrp_legal":17,"spouse_consent_mrp":1.5,"mortgage_contract_mrp":4,"pledge_mrp":4,"valuation_min":20000,"usd_rate":null}$q$::jsonb),
  ($q$home$q$, $q${"hero_title":"Недвижимость и оценка имущества в Казахстане","hero_sub":"Подберём, продадим или сдадим объект, проверим документы и проведём сделку. Оценим квартиру, дом, автомобиль, оборудование и бизнес для банка, нотариуса или суда.","promise":"Перезваниваем в течение 15 минут в рабочее время"}$q$::jsonb)
