  (3, $q$uchastok$q$, $q$real_estate$q$, $q$Земельный участок$q$, $q$ИЖС, сельхозназначение, участки под коммерцию.$q$, $q$Стоимость права собственности или права землепользования. Учитываем целевое назначение, площадь, локацию, подъезд и коммуникации.$q$, array[$q$Купля-продажа$q$, $q$Залог$q$, $q$Изъятие для государственных нужд$q$, $q$Наследство$q$, $q$Уставный капитал$q$]::text[], array[$q$Идентификационный документ на земельный участок$q$, $q$Правоустанавливающий документ$q$, $q$Кадастровый номер / план участка$q$, $q$Удостоверение личности или документы юрлица$q$]::text[], 30000, $q$от 30 000 ₸$q$, $q$2–3 рабочих дня$q$, 3, true),
  (4, $q$kommercheskaya$q$, $q$real_estate$q$, $q$Коммерческая недвижимость$q$, $q$Офисы, магазины, склады, производственные базы, ПСН.$q$, $q$Для коммерции ключевой — доходный подход: арендные ставки, заполняемость, операционные расходы и ставка капитализации. Дополнительно — сравнительный и затратный.$q$, array[$q$Залог в банке$q$, $q$Купля-продажа$q$, $q$Уставный капитал$q$, $q$МСФО и переоценка$q$, $q$Суд и банкротство$q$]::text[], array[$q$Правоустанавливающие документы$q$, $q$Технический паспорт$q$, $q$Документы на землю$q$, $q$Договоры аренды и сведения о доходах (для доходного подхода)$q$, $q$Учредительные документы (для юрлица)$q$]::text[], 80000, $q$от 80 000 ₸$q$, $q$3–7 рабочих дней$q$, 4, true),
