  (6, $q$stavka-arendy$q$, $q$real_estate$q$, $q$Рыночная ставка аренды$q$, $q$Сколько стоит аренда объекта по рынку.$q$, $q$Обоснованная рыночная ставка аренды для договора, спора с арендатором, расчёта налогов или переговоров.$q$, array[$q$Договор аренды$q$, $q$Суд$q$, $q$Налоговый учёт$q$]::text[], array[$q$Документы на объект$q$, $q$Технический паспорт$q$, $q$Действующий договор аренды (если есть)$q$]::text[], 25000, $q$от 25 000 ₸$q$, $q$1–3 рабочих дня$q$, 6, true),
