  (9, $q$oborudovanie$q$, $q$equipment$q$, $q$Оборудование и производственные линии$q$, $q$Станки, линии, медицинское, торговое и офисное оборудование.$q$, $q$Затратный и сравнительный подходы: стоимость замещения, физический, функциональный и экономический износ. Работаем с перечнями от одной позиции до тысяч.$q$, array[$q$Залог$q$, $q$Уставный капитал$q$, $q$МСФО и переоценка$q$, $q$Страхование$q$, $q$Банкротство$q$]::text[], array[$q$Перечень / инвентарная ведомость$q$, $q$Паспорта оборудования$q$, $q$Договоры и счета-фактуры о приобретении$q$, $q$Балансовая стоимость и дата ввода$q$, $q$Доступ на осмотр$q$]::text[], 50000, $q$от 50 000 ₸$q$, $q$3–10 рабочих дней$q$, 9, true),
  (10, $q$tmz$q$, $q$equipment$q$, $q$Товарные запасы и сырьё$q$, $q$Товары на складе, материалы, готовая продукция.$q$, $q$Оценка ТМЗ по рыночным ценам с учётом ликвидности, сроков годности и объёма партии.$q$, array[$q$Залог товаров в обороте$q$, $q$Банкротство$q$, $q$МСФО$q$, $q$Страхование$q$]::text[], array[$q$Складская ведомость$q$, $q$Документы о поставке$q$, $q$Сведения о сроках годности$q$, $q$Доступ на склад$q$]::text[], 50000, $q$от 50 000 ₸$q$, $q$3–7 рабочих дней$q$, 10, true),
  (11, $q$bytovoe$q$, $q$equipment$q$, $q$Бытовое имущество и ценности$q$, $q$Мебель, техника, ювелирные изделия, коллекции.$q$, $q$Для раздела имущества, наследства и страхования: опись, фотофиксация и рыночная стоимость с учётом износа.$q$, array[$q$Раздел имущества$q$, $q$Наследство$q$, $q$Страхование$q$, $q$Суд$q$]::text[], array[$q$Перечень имущества$q$, $q$Чеки и гарантийные талоны (при наличии)$q$, $q$Доступ для осмотра$q$]::text[], 20000, $q$от 20 000 ₸$q$, $q$1–3 рабочих дня$q$, 11, true),
  (12, $q$biznes$q$, $q$business$q$, $q$Бизнес, доли в ТОО, акции$q$, $q$Стоимость компании или доли для сделки, раздела и суда.$q$, $q$Доходный подход (дисконтирование денежных потоков), сравнительный по сделкам с аналогами и затратный (метод чистых активов). Учитываем контроль и ликвидность доли.$q$, array[$q$Купля-продажа бизнеса или доли$q$, $q$Выход участника из ТОО$q$, $q$Раздел имущества$q$, $q$Наследство$q$, $q$Привлечение инвестора$q$, $q$Суд$q$]::text[], array[$q$Учредительные документы$q$, $q$Бухгалтерская отчётность за 3 года$q$, $q$Расшифровки основных средств, дебиторской и кредиторской задолженности$q$, $q$Кредитные договоры$q$, $q$Договоры аренды$q$, $q$Бизнес-план или прогноз$q$]::text[], 300000, $q$от 300 000 ₸$q$, $q$7–20 рабочих дней$q$, 12, true),
  (13, $q$nma$q$, $q$business$q$, $q$Нематериальные активы$q$, $q$Товарные знаки, программы, лицензии, права аренды и землепользования.$q$, $q$Оценка интеллектуальной собственности и прав: товарный знак, программное обеспечение, франшиза, права аренды и землепользования.$q$, array[$q$Уставный капитал$q$, $q$МСФО$q$, $q$Продажа и лицензирование$q$, $q$Суд$q$]::text[], array[$q$Охранные документы / свидетельства$q$, $q$Лицензионные договоры$q$, $q$Данные о доходах от актива$q$]::text[], 150000, $q$от 150 000 ₸$q$, $q$7–15 рабочих дней$q$, 13, true),
  (14, $q$msfo$q$, $q$business$q$, $q$Переоценка основных средств по МСФО$q$, $q$Справедливая стоимость активов для отчётности.$q$, $q$Переоценка зданий, оборудования и транспорта для финансовой отчётности, тест на обесценение, оценка для аудитора.$q$, array[$q$Финансовая отчётность$q$, $q$Аудит$q$, $q$Тест на обесценение$q$]::text[], array[$q$Реестр основных средств$q$, $q$Учётная политика$q$, $q$Документы на ключевые активы$q$]::text[], 200000, $q$от 200 000 ₸, по объёму реестра$q$, $q$по смете$q$, 14, true),
  (15, $q$zaliv$q$, $q$damage$q$, $q$Ущерб после залива или пожара$q$, $q$Стоимость ремонта и повреждённого имущества.$q$, $q$Осмотр с уведомлением виновной стороны, дефектная ведомость, смета восстановительного ремонта и оценка повреждённой мебели и техники.$q$, array[$q$Досудебная претензия$q$, $q$Страховая выплата$q$, $q$Суд$q$]::text[], array[$q$Акт ОСИ / КСК о заливе (с участием сторон)$q$, $q$Документы на квартиру$q$, $q$Удостоверение личности$q$, $q$Фото повреждений$q$, $q$Чеки на имущество и ремонт (при наличии)$q$]::text[], 30000, $q$от 30 000 ₸$q$, $q$2–5 рабочих дней$q$, 15, true),
  (16, $q$dtp$q$, $q$damage$q$, $q$Ущерб автомобилю после ДТП$q$, $q$Стоимость восстановительного ремонта и утраты товарной стоимости.$q$, $q$Независимая оценка ущерба для страховой компании или суда, когда сумма выплаты по ОГПО ВТС кажется заниженной.$q$, array[$q$Спор со страховой$q$, $q$Претензия виновнику$q$, $q$Суд$q$]::text[], array[$q$Свидетельство о регистрации ТС$q$, $q$Документы о ДТП (протокол, схема или извещение)$q$, $q$Полис ОГПО ВТС$q$, $q$Автомобиль до ремонта$q$]::text[], 20000, $q$от 20 000 ₸$q$, $q$1–3 рабочих дня$q$, 16, true)
insert into public.valuation_purposes (id, title, required_by, value_kind, description, sort) values
  (1, $q$Ипотека и залог в банке$q$, $q$Банк, Отбасы банк$q$, $q$Рыночная (банк может применить залоговый дисконт)$q$, $q$Банк выдаёт заём под залог и опирается на отчёт об оценке. Заёмщик вправе сам выбрать оценочную компанию — банк не может обязать обращаться к конкретному оценщику.$q$, 1),
  (2, $q$Наследство у нотариуса$q$, $q$Нотариус, наследники$q$, $q$Рыночная на дату открытия наследства$q$, $q$Отчёт фиксирует стоимость наследственного имущества. По новому Налоговому кодексу (с 2026 года) при последующей продаже наследства первоначальной стоимостью для расчёта ИПН считается рыночная стоимость по отчёту об оценке — без него налог посчитают со всей суммы.$q$, 2),
  (3, $q$Раздел имущества супругов$q$, $q$Суд, стороны, медиатор$q$, $q$Рыночная$q$, $q$Нужна, чтобы справедливо разделить квартиру, автомобиль, бизнес или долю, рассчитать компенсацию одному из супругов.$q$, 3),
  (4, $q$Суд и исполнительное производство$q$, $q$Суд, частный судебный исполнитель$q$, $q$Рыночная или ликвидационная$q$, $q$Обоснование цены иска, оспаривание оценки арестованного имущества, определение стоимости для торгов.$q$, 4),
  (5, $q$Купля-продажа$q$, $q$Продавец, покупатель$q$, $q$Рыночная$q$, $q$Не обязательна, но помогает назначить цену и аргументировать её в переговорах, снижает риск споров.$q$, 5),
  (6, $q$Дарение и сделки между родственниками$q$, $q$Стороны, нотариус$q$, $q$Рыночная$q$, $q$Подтверждает стоимость имущества для договора и будущих налоговых расчётов.$q$, 6),
  (7, $q$Страхование$q$, $q$Страховая компания$q$, $q$Рыночная или стоимость замещения$q$, $q$Определяет страховую сумму, чтобы при страховом случае выплата покрыла реальный ущерб.$q$, 7),
  (8, $q$Вклад в уставный капитал ТОО$q$, $q$Учредители, регистрирующий орган$q$, $q$Рыночная$q$, $q$Имущество, вносимое в уставный капитал, оценивается, чтобы подтвердить его денежную стоимость.$q$, 8),
  (9, $q$Бухгалтерский учёт и МСФО$q$, $q$Бухгалтерия, аудитор$q$, $q$Справедливая$q$, $q$Переоценка основных средств, тест на обесценение, распределение цены покупки бизнеса.$q$, 9),
  (10, $q$Изъятие земли для государственных нужд$q$, $q$Акимат$q$, $q$Рыночная$q$, $q$Определение размера возмещения собственнику при выкупе участка и недвижимости государством.$q$, 10),
  (11, $q$Возмещение ущерба$q$, $q$Виновник, страховая, суд$q$, $q$Стоимость восстановительного ремонта$q$, $q$Залив, пожар, ДТП: отчёт — основа претензии и иска.$q$, 11),
  (12, $q$Банкротство и реабилитация$q$, $q$Финансовый управляющий, кредиторы$q$, $q$Рыночная и ликвидационная$q$, $q$Оценка имущественной массы должника для торгов и расчётов с кредиторами.$q$, 12)
insert into public.process_steps (id, process, step_no, title, description, duration) values
  (1, $q$buy$q$, 1, $q$Заявка и консультация$q$, $q$Обсуждаем бюджет, район, сроки, способ оплаты. Если нужна ипотека — сразу считаем платёж и предварительное одобрение.$q$, $q$1 день$q$),
  (2, $q$buy$q$, 2, $q$Подбор вариантов$q$, $q$Подбираем объекты по нашей базе и порталам, отсеиваем неликвид и проблемные варианты, присылаем подборку с комментариями.$q$, $q$2–7 дней$q$),
  (3, $q$buy$q$, 3, $q$Показы$q$, $q$Организуем просмотры в удобное время, проверяем дом, подъезд, соседей, инфраструктуру и реальное состояние квартиры.$q$, $q$1–2 недели$q$),
  (4, $q$buy$q$, 4, $q$Проверка юридической чистоты$q$, $q$Проверяем собственника, обременения, аресты, долги, историю переходов права, согласие супруга и права детей.$q$, $q$1–3 дня$q$),
  (5, $q$buy$q$, 5, $q$Торг и задаток$q$, $q$Ведём переговоры о цене, фиксируем договорённости в авансовом соглашении или соглашении о задатке.$q$, $q$1–3 дня$q$),
  (6, $q$buy$q$, 6, $q$Сделка$q$, $q$Договор купли-продажи у нотариуса, в ЦОН или через eGov, безопасная схема расчётов.$q$, $q$1 день$q$),
  (7, $q$buy$q$, 7, $q$Регистрация и ключи$q$, $q$Контролируем регистрацию права собственности и подписываем акт приёма-передачи с показаниями счётчиков.$q$, $q$1–3 рабочих дня$q$),
  (8, $q$sell$q$, 1, $q$Оценка рыночной цены$q$, $q$Анализируем аналоги и реальные сделки, предлагаем стратегию цены и сроки.$q$, $q$1 день$q$),
  (9, $q$sell$q$, 2, $q$Договор$q$, $q$Фиксируем комиссию, обязанности и срок работы. Никаких скрытых платежей.$q$, $q$1 день$q$),
  (10, $q$sell$q$, 3, $q$Подготовка и съёмка$q$, $q$Советы по подготовке, при необходимости — хоумстейджинг; фото, видео и планировка.$q$, $q$2–5 дней$q$),
  (11, $q$sell$q$, 4, $q$Реклама$q$, $q$Размещаем объявление на krisha.kz, olx.kz, в соцсетях и по базе покупателей.$q$, $q$весь срок продажи$q$),
  (12, $q$sell$q$, 5, $q$Показы и переговоры$q$, $q$Проводим показы, проверяем покупателя и его финансирование, отстаиваем вашу цену.$q$, $q$2–6 недель$q$),
  (13, $q$sell$q$, 6, $q$Задаток и документы$q$, $q$Подписываем соглашение о задатке, собираем документы, снимаем с регистрации жильцов.$q$, $q$3–10 дней$q$),
  (14, $q$sell$q$, 7, $q$Сделка и расчёты$q$, $q$Договор, получение денег по согласованной схеме, регистрация, передача ключей.$q$, $q$1–3 дня$q$),
  (15, $q$rent$q$, 1, $q$Оценка ставки$q$, $q$Считаем рыночную ставку по аналогам в районе и состоянию квартиры.$q$, $q$1 день$q$),
  (16, $q$rent$q$, 2, $q$Поиск арендатора$q$, $q$Реклама, показы, проверка арендатора: документы, место работы, цель проживания.$q$, $q$3–14 дней$q$),
  (17, $q$rent$q$, 3, $q$Договор и акт$q$, $q$Договор найма, акт приёма-передачи с описью имущества, фото и показаниями счётчиков.$q$, $q$1 день$q$),
  (18, $q$rent$q$, 4, $q$Депозит и оплата$q$, $q$Принимаем первый платёж и страховой депозит, фиксируем порядок оплаты коммунальных.$q$, $q$1 день$q$),
  (19, $q$rent$q$, 5, $q$Сопровождение$q$, $q$По договору управления — сбор платы, осмотры, решение бытовых вопросов.$q$, $q$весь срок аренды$q$),
  (20, $q$valuation$q$, 1, $q$Заявка и цель оценки$q$, $q$Уточняем объект и цель: банк, нотариус, суд, раздел, МСФО. От цели зависит вид стоимости и требования к отчёту.$q$, $q$15 минут$q$),
  (21, $q$valuation$q$, 2, $q$Договор и стоимость$q$, $q$Называем цену и срок до начала работы, заключаем договор на оценку.$q$, $q$в день обращения$q$),
  (22, $q$valuation$q$, 3, $q$Документы$q$, $q$Присылаете копии документов — фото с телефона подходят для начала работы.$q$, $q$1 день$q$),
  (23, $q$valuation$q$, 4, $q$Осмотр$q$, $q$Оценщик осматривает и фотографирует объект — без осмотра отчёт не составляется.$q$, $q$1 день$q$),
  (24, $q$valuation$q$, 5, $q$Расчёт$q$, $q$Анализ рынка, подбор аналогов, расчёт сравнительным, доходным и затратным подходами, согласование результата.$q$, $q$1–10 дней$q$),
  (25, $q$valuation$q$, 6, $q$Отчёт$q$, $q$Отчёт об оценке с подписью оценщика: электронная версия сразу, бумажная — в офисе или курьером.$q$, $q$в день готовности$q$),
  (26, $q$mortgage$q$, 1, $q$Расчёт бюджета$q$, $q$Считаем доступный платёж, первоначальный взнос и переплату по разным программам.$q$, $q$1 день$q$),
  (27, $q$mortgage$q$, 2, $q$Выбор программы$q$, $q$Госпрограммы Отбасы банка или коммерческий банк — выбираем выгодную и реальную для вас.$q$, $q$1–2 дня$q$),
  (28, $q$mortgage$q$, 3, $q$Документы$q$, $q$Собираем пакет заёмщика и созаёмщиков, подтверждение дохода.$q$, $q$2–5 дней$q$),
  (29, $q$mortgage$q$, 4, $q$Одобрение$q$, $q$Подаём заявки, отвечаем на запросы банков, получаем решение.$q$, $q$3–10 дней$q$),
  (30, $q$mortgage$q$, 5, $q$Оценка и страховка$q$, $q$Оценка залога и страхование объекта по требованиям банка.$q$, $q$1–3 дня$q$),
  (31, $q$mortgage$q$, 6, $q$Сделка$q$, $q$Договор купли-продажи, договор займа и залога, регистрация права и обременения.$q$, $q$1–5 дней$q$)
insert into public.checklists (id, slug, title, audience, intro, items, sort) values
  (1, $q$prodazha-kvartiry$q$, $q$Документы для продажи квартиры$q$, $q$Продавцу$q$, $q$Минимальный пакет для сделки на вторичном рынке. Справки из госбаз нотариус и ЦОН получают сами, но проверить их заранее стоит — это ускоряет сделку.$q$, $q$[{"title":"Удостоверение личности всех собственников","note":"Должно быть действительным. Если собственник — ребёнок до 18 лет, нужно свидетельство о рождении."},{"title":"Правоустанавливающий документ","note":"Договор купли-продажи, дарения, мены, свидетельство о праве на наследство, ДДУ с актом приёма-передачи, решение суда."},{"title":"Подтверждение регистрации права","note":"Для квартир, купленных с 2013 года, — уведомление о госрегистрации; для более ранних — отметка о регистрации на договоре."},{"title":"Технический паспорт","note":"Планировка в техпаспорте должна совпадать с фактической. Неузаконенная перепланировка мешает ипотеке."},{"title":"Нотариальное согласие супруга(и)","note":"Если квартира куплена в браке. Стоимость у нотариуса в 2026 году — 1,5 МРП (≈ 6 488 ₸)."},{"title":"Разрешение органа опеки","note":"Если среди собственников или проживающих есть несовершеннолетние."},{"title":"Справка об отсутствии обременений и арестов","note":"Бесплатно на eGov или у нотариуса из государственной базы."},{"title":"Отсутствие долгов по коммунальным услугам","note":"Справка или квитанции от ОСИ / КСК и поставщиков услуг."},{"title":"Выписка с жильцов","note":"Желательно до сделки снять с регистрации всех, кто прописан по адресу."},{"title":"Доверенность","note":"Если продаёт представитель — нотариальная доверенность с правом продажи и получения денег."}]$q$::jsonb, 1),
  (2, $q$pokupka-kvartiry$q$, $q$Что проверить перед покупкой квартиры$q$, $q$Покупателю$q$, $q$Список проверок, которые защищают от потери денег. Агентство выполняет их в рамках проверки юридической чистоты.$q$, $q$[{"title":"Личность продавца и совпадение с собственником","note":"Сверьте удостоверение с правоустанавливающим документом."},{"title":"История переходов права","note":"Частые перепродажи за короткий срок — повод для углублённой проверки."},{"title":"Обременения, залоги и аресты","note":"Справка о зарегистрированных правах и обременениях, проверка по реестру должников."},{"title":"Супруги и бывшие супруги","note":"Согласие супруга, если квартира приобретена в браке; при разводе — как разделено имущество."},{"title":"Дети и прописанные лица","note":"Права несовершеннолетних, разрешение опеки, кто зарегистрирован в квартире."},{"title":"Наследственные риски","note":"Если квартира получена по наследству недавно — нет ли других наследников, которые могут заявить права."},{"title":"Соответствие планировки техпаспорту","note":"Неузаконенная перепланировка — ваш риск и расходы после покупки."},{"title":"Долги за коммунальные услуги и налоги","note":"Попросите квитанции и справки об отсутствии задолженности."},{"title":"Схема расчётов","note":"Не передавайте всю сумму до подписания договора. Используйте банковскую ячейку, перевод через банк или депозит нотариуса."},{"title":"Задаток","note":"Оформляйте письменно и указывайте, что это именно задаток или аванс — последствия отказа от сделки разные."}]$q$::jsonb, 2),
  (3, $q$ipoteka$q$, $q$Пакет документов для ипотеки$q$, $q$Заёмщику$q$, $q$Типовой список. Каждый банк и программа Отбасы банка могут запросить дополнительные документы.$q$, $q$[{"title":"Удостоверение личности заёмщика и созаёмщиков","note":""},{"title":"Подтверждение дохода","note":"Банки получают сведения о пенсионных взносах из ГЦВП с вашего согласия; дополнительно — справка с работы."},{"title":"Свидетельство о браке / разводе, согласие супруга","note":""},{"title":"Документы на приобретаемую квартиру","note":"Правоустанавливающий документ, техпаспорт продавца, ДДУ для новостроек."},{"title":"Отчёт об оценке залога","note":"Оценщика можно выбрать самостоятельно; стоимость — от 20 000 ₸."},{"title":"Подтверждение первоначального взноса","note":"Выписка со счёта, депозит в Отбасы банке."},{"title":"Для госпрограмм","note":"Сведения об отсутствии жилья у вас и членов семьи (для «Наурыз» — за последние 5 лет), документы о статусе (для льготных категорий)."}]$q$::jsonb, 3),
  (4, $q$sdat-v-arendu$q$, $q$Сдаёте квартиру: что подготовить$q$, $q$Собственнику$q$, $q$Чтобы аренда не превратилась в спор, всё фиксируется на бумаге.$q$, $q$[{"title":"Документы на квартиру и удостоверение личности","note":"Арендатор вправе убедиться, что сдаёт собственник."},{"title":"Договор найма жилища","note":"Срок, ставка, порядок оплаты коммунальных, депозит, условия расторжения, кто платит за ремонт."},{"title":"Акт приёма-передачи с описью","note":"Перечень мебели и техники, фото состояния, показания счётчиков."},{"title":"Страховой депозит","note":"Обычно — одна месячная ставка, возвращается при выезде без повреждений."},{"title":"Налоги с дохода от аренды","note":"Доход физлица от сдачи жилья облагается ИПН. Правила изменились с 2026 года — уточните порядок декларирования на kgd.gov.kz или у нас на консультации."}]$q$::jsonb, 4),
  (5, $q$snyat-kvartiru$q$, $q$Снимаете квартиру: что проверить$q$, $q$Арендатору$q$, $q$Пять минут проверки экономят депозит и нервы.$q$, $q$[{"title":"Кто сдаёт квартиру","note":"Собственник по документам или представитель по нотариальной доверенности."},{"title":"Нет ли ареста или залога","note":"Арестованную квартиру могут забрать вместе с вашим сроком аренды."},{"title":"Договор в письменной форме","note":"Без договора депозит почти невозможно вернуть."},{"title":"Акт с фото и счётчиками","note":"Сфотографируйте все дефекты до въезда и впишите их в акт."},{"title":"Порядок оплаты","note":"Переводите на счёт собственника, сохраняйте подтверждения."}]$q$::jsonb, 5),
  (6, $q$darenie$q$, $q$Дарение недвижимости$q$, $q$Дарителю и одаряемому$q$, $q$Договор дарения регистрируется так же, как купля-продажа.$q$, $q$[{"title":"Удостоверения личности сторон","note":""},{"title":"Правоустанавливающий документ и техпаспорт","note":""},{"title":"Согласие супруга дарителя","note":"Если имущество приобретено в браке."},{"title":"Документы о родстве","note":"Свидетельства о рождении, браке — для сниженного нотариального тарифа (7 МРП вместо 12 МРП)."},{"title":"Налоги","note":"Для одаряемого — не близкого родственника — возможен доход, облагаемый ИПН. При будущей продаже подаренного жилья первоначальной стоимостью считается оценочная стоимость для налога на имущество на 1 января года получения."}]$q$::jsonb, 6),
  (7, $q$nasledstvo$q$, $q$Наследство на недвижимость$q$, $q$Наследникам$q$, $q$Наследство открывается со дня смерти наследодателя; заявление нотариусу подаётся в течение шести месяцев.$q$, $q$[{"title":"Свидетельство о смерти","note":""},{"title":"Документы, подтверждающие родство","note":"Свидетельства о рождении, браке."},{"title":"Завещание (если есть)","note":""},{"title":"Правоустанавливающие документы на имущество","note":"Договор, техпаспорт, документы на землю."},{"title":"Отчёт об оценке","note":"Для нотариуса и для будущей продажи: с 2026 года стоимость по отчёту — первоначальная стоимость при расчёте ИПН."},{"title":"Регистрация права после свидетельства","note":"Свидетельство о праве на наследство регистрируется через ЦОН, нотариуса или eGov."}]$q$::jsonb, 7),
  (8, $q$novostroyka$q$, $q$Покупка в новостройке$q$, $q$Покупателю$q$, $q$Главное — понять, по какой схеме застройщик привлекает деньги дольщиков.$q$, $q$[{"title":"Разрешение акимата на привлечение денег дольщиков","note":"Без него продажа квартир в строящемся доме незаконна."},{"title":"Схема финансирования","note":"Гарантия АО «Казахстанская жилищная компания», продажа после возведения каркаса или проектное финансирование банка."},{"title":"Договор о долевом участии","note":"Учётная регистрация ДДУ, срок сдачи, площадь и порядок перерасчёта, штрафы за просрочку."},{"title":"Опыт застройщика","note":"Сданные объекты, сроки, суды, отзывы жителей."},{"title":"Тип отделки","note":"Черновая, предчистовая или чистовая — от этого зависит взнос по «Наурыз» (10% только для чистовой)."},{"title":"Приёмка квартиры","note":"Акт замечаний с перечнем дефектов, проверка площади и коммуникаций."}]$q$::jsonb, 8),
  (9, $q$dom-uchastok$q$, $q$Покупка дома и участка$q$, $q$Покупателю$q$, $q$Помимо проверки квартиры добавляются земля и строения.$q$, $q$[{"title":"Идентификационный документ на землю","note":"Кадастровый номер, площадь, целевое назначение (ИЖС, садоводство, сельхоз)."},{"title":"Правоустанавливающие документы на дом и участок","note":"Дом и земля должны принадлежать одному собственнику."},{"title":"Техпаспорт на дом и все строения","note":"Неоформленные пристройки и бани — частая проблема."},{"title":"Границы участка","note":"Совпадает ли забор с кадастровым планом, нет ли споров с соседями."},{"title":"Коммуникации","note":"Документы на подключение газа, электричества, воды, канализации."},{"title":"Ограничения","note":"Охранные зоны ЛЭП, газопроводов, водоохранные зоны, планы изъятия."}]$q$::jsonb, 9),
  (10, $q$ocenka-kvartiry$q$, $q$Документы для оценки квартиры или дома$q$, $q$Заказчику оценки$q$, $q$Для начала работы достаточно фото документов с телефона.$q$, $q$[{"title":"Удостоверение личности заказчика","note":""},{"title":"Правоустанавливающий документ","note":""},{"title":"Технический паспорт","note":""},{"title":"Документ на земельный участок","note":"Для домов и участков."},{"title":"Данные покупателя и продавца","note":"Для ипотеки — банк укажет, какие сведения нужны в отчёте."},{"title":"Доступ на осмотр","note":"Оценщик фотографирует все помещения, фасад и подъезд."}]$q$::jsonb, 10),
  (11, $q$ocenka-avto$q$, $q$Документы для оценки автомобиля и техники$q$, $q$Заказчику оценки$q$, $q$$q$, $q$[{"title":"Свидетельство о регистрации ТС","note":"Или паспорт самоходной машины для спецтехники."},{"title":"Удостоверение личности собственника","note":"Или доверенность, или документы нотариуса — для наследства."},{"title":"Сведения о пробеге, ремонтах, ДТП","note":""},{"title":"Транспорт для осмотра","note":"Осмотр в светлое время, чистый автомобиль."}]$q$::jsonb, 11),
  (12, $q$ocenka-biznesa$q$, $q$Документы для оценки бизнеса и оборудования$q$, $q$Заказчику оценки$q$, $q$$q$, $q$[{"title":"Учредительные документы и сведения о долях","note":""},{"title":"Бухгалтерская отчётность за 3 года","note":"Баланс, отчёт о прибылях и убытках, движение денежных средств."},{"title":"Расшифровки активов и обязательств","note":"Основные средства, дебиторская и кредиторская задолженность, кредиты."},{"title":"Перечень оборудования","note":"С инвентарными номерами, годом выпуска, балансовой стоимостью."},{"title":"Документы о приобретении","note":"Договоры, счета-фактуры, паспорта оборудования."},{"title":"Прогноз или бизнес-план","note":"Для доходного подхода."}]$q$::jsonb, 12),
  (13, $q$den-sdelki$q$, $q$День сделки: чек-лист$q$, $q$Продавцу и покупателю$q$, $q$Чтобы не пришлось переносить сделку из-за мелочи.$q$, $q$[{"title":"Оригиналы всех документов","note":"Удостоверения, правоустанавливающие документы, техпаспорт, согласие супруга."},{"title":"Подтверждение денег","note":"Банк, ячейка или депозит нотариуса подготовлены заранее."},{"title":"Сверка цены в договоре","note":"В договоре указывается реальная цена — от неё зависит ИПН и защита покупателя."},{"title":"Оплата госпошлины за регистрацию","note":"За квартиру или дом — 1 304 ₸ (данные krisha.kz на 2026 год)."},{"title":"Акт приёма-передачи","note":"Ключи, показания счётчиков, состояние квартиры."},{"title":"Контроль регистрации","note":"Сделка завершена, когда в личном кабинете eGov покупателя пришло уведомление о регистрации."}]$q$::jsonb, 13)
insert into public.faq (id, category, question, answer, sort, is_active) values
  (1, $q$Покупка$q$, $q$Обязательно ли заверять договор купли-продажи у нотариуса?$q$, $q$Нет. Законодательство не обязывает нотариально удостоверять сделку с жильём: договор можно оформить в ЦОН или через eGov с ЭЦП. Нотариус дороже (в 2026 году — 12 МРП для не родственников), но дополнительно проверяет стороны и документы.$q$, 1, true),
  (2, $q$Покупка$q$, $q$Когда я становлюсь собственником квартиры?$q$, $q$Только после государственной регистрации права. Подписанный договор — лишь основание для регистрации. Стандартный срок регистрации — 3 рабочих дня, ускоренная — около 2 часов за дополнительную плату.$q$, 2, true),
  (3, $q$Покупка$q$, $q$Чем задаток отличается от аванса?$q$, $q$Задаток обеспечивает исполнение договора: если сделку сорвёт покупатель, задаток остаётся у продавца; если продавец — он возвращает задаток в двойном размере. Аванс — просто часть оплаты, при срыве сделки возвращается. Важно, как именно платёж назван в соглашении.$q$, 3, true),
  (4, $q$Покупка$q$, $q$Как безопасно передать деньги продавцу?$q$, $q$Используйте банковскую ячейку с доступом продавца после регистрации, банковский перевод после регистрации права или депозит нотариуса. Не передавайте наличные до подписания договора и без расписки.$q$, 4, true),
  (5, $q$Продажа$q$, $q$Сколько времени занимает продажа квартиры?$q$, $q$При рыночной цене и хорошей подготовке — в среднем 30–60 дней. Завышенная на 10–15% цена может растянуть продажу на месяцы.$q$, 5, true),
  (6, $q$Продажа$q$, $q$Нужно ли платить налог при продаже квартиры?$q$, $q$ИПН платится только с прироста стоимости (цена продажи минус цена покупки) и только если вы владели жильём меньше установленного срока: 1 год — для права, зарегистрированного до 1 января 2026 года, 2 года — для зарегистрированного после. Ставка 10%, с суммы прироста свыше 8 500 МРП за год — 15%.$q$, 6, true),
  (7, $q$Продажа$q$, $q$Можно ли продать квартиру в ипотеке?$q$, $q$Да, с согласия банка: покупатель или сам продавец гасит остаток займа, банк снимает обременение, затем регистрируется переход права. Часто сделка проводится одновременно с погашением.$q$, 7, true),
  (8, $q$Продажа$q$, $q$Почему агентство просит эксклюзивный договор?$q$, $q$Эксклюзив — договор с одним агентством. Объект не «размывается» десятком одинаковых объявлений с разными ценами, а агентство вкладывает в рекламу и съёмку. Срок и условия выхода фиксируются в договоре.$q$, 8, true),
  (9, $q$Аренда$q$, $q$Кто платит комиссию при аренде?$q$, $q$По договорённости. Чаще всего собственник платит около 50% месячной ставки, если агентство нашло арендатора; при поиске квартиры для арендатора — 50–100% ставки. Условия всегда в договоре.$q$, 9, true),
  (10, $q$Аренда$q$, $q$Зачем нужен акт приёма-передачи?$q$, $q$Это единственный документ, который доказывает, в каком состоянии квартира и вещи были при въезде. Без него трудно вернуть депозит или взыскать ущерб.$q$, 10, true),
  (11, $q$Оценка$q$, $q$Сколько стоит оценка квартиры для банка?$q$, $q$От 20 000 ₸. Цена зависит от типа объекта, площади, срочности и цели оценки. Точную стоимость называем до начала работы.$q$, 11, true),
  (12, $q$Оценка$q$, $q$Сколько действует отчёт об оценке?$q$, $q$Единого срока закон не устанавливает. В отчёте указывается дата оценки, а банки, нотариусы и госорганы сами определяют, отчёт какой давности принимают. Уточните требование у получателя заранее.$q$, 12, true),
  (13, $q$Оценка$q$, $q$Можно ли не ехать на осмотр?$q$, $q$Осмотр объекта — обязательная часть оценки. Присутствовать может представитель собственника, достаточно обеспечить доступ.$q$, 13, true),
  (14, $q$Оценка$q$, $q$Банк направляет к своему оценщику — это обязательно?$q$, $q$Нет. Заёмщик вправе сам выбрать оценочную компанию; важно, чтобы оценщик имел квалификационное свидетельство и состоял в палате оценщиков.$q$, 14, true),
  (15, $q$Оценка$q$, $q$Чем онлайн-оценка на сайте отличается от отчёта?$q$, $q$Онлайн-калькулятор показывает ориентир по средним ценам и типовым поправкам. Официальный отчёт готовит оценщик после осмотра и анализа конкретных аналогов — только он принимается банком, нотариусом и судом.$q$, 15, true),
  (16, $q$Оценка$q$, $q$Какие подходы используются при оценке?$q$, $q$Сравнительный (по ценам аналогов — основной для квартир), доходный (по будущему доходу — для коммерции и бизнеса) и затратный (стоимость создания объекта за вычетом износа — для специализированных объектов и оборудования).$q$, 16, true),
  (17, $q$Ипотека$q$, $q$Какой первоначальный взнос по программе «Наурыз»?$q$, $q$От 10% — при покупке нового жилья с чистовой отделкой, от 20% — для черновой отделки и вторичного рынка. Ставка — 9%, для социально уязвимых категорий — 7%, срок до 19 лет.$q$, 17, true),
  (18, $q$Ипотека$q$, $q$Можно ли взять ипотеку на вторичное жильё?$q$, $q$Да: в коммерческих банках (ставки в 2026 году — около 18–20% и выше) и по ряду программ Отбасы банка с взносом от 20%. Банк проверит дом: возраст, отсутствие арестов и неузаконенных перепланировок.$q$, 18, true),
  (19, $q$Документы и налоги$q$, $q$Что такое МРП и почему все тарифы в МРП?$q$, $q$Месячный расчётный показатель — единица для расчёта пошлин, штрафов и тарифов. В 2026 году 1 МРП = 4 325 ₸. Нотариальное удостоверение договора между не родственниками — 12 МРП (51 900 ₸).$q$, 19, true),
  (20, $q$Документы и налоги$q$, $q$Когда подавать декларацию после продажи?$q$, $q$Декларация по форме 270.00 подаётся до 15 сентября года, следующего за годом продажи, налог уплачивается до 25 сентября.$q$, 20, true),
  (21, $q$Документы и налоги$q$, $q$Как узаконить перепланировку?$q$, $q$Нужны эскизный проект, согласования, акт приёмки и изменения в техническом паспорте. Без этого возможны проблемы с продажей и отказ банка в ипотеке.$q$, 21, true),
  (22, $q$Об агентстве$q$, $q$Нужна ли агентству лицензия?$q$, $q$Сейчас риэлторская деятельность в Казахстане не лицензируется; законопроект о её регулировании обсуждается. Риэлторы являются субъектами финансового мониторинга. Оценочная деятельность регулируется законом: оценщик должен иметь квалификационное свидетельство и состоять в палате оценщиков.$q$, 22, true),
  (23, $q$Об агентстве$q$, $q$Когда и сколько я плачу агентству?$q$, $q$Сумма и момент оплаты фиксируются в договоре до начала работы. Обычно комиссия оплачивается в день сделки. Мы не берём предоплату за показы.$q$, 23, true),
  (24, $q$Об агентстве$q$, $q$Работаете ли вы с другими городами?$q$, $q$Да. Сделки и оценку проводим по всему Казахстану: часть работы — дистанционно, осмотр и показы — силами партнёров на месте.$q$, 24, true)
insert into public.glossary (id, term, definition) values
  (1, $q$Авансовое соглашение$q$, $q$Письменная договорённость о будущей сделке с внесением аванса: фиксирует цену, сроки и условия.$q$),
  (2, $q$Задаток$q$, $q$Сумма в счёт будущей оплаты, которая одновременно обеспечивает исполнение договора: при отказе покупателя остаётся у продавца, при отказе продавца возвращается в двойном размере.$q$),
  (3, $q$Альтернативная сделка$q$, $q$Одновременная продажа одного объекта и покупка другого, связанные общими сроками и расчётами.$q$),
  (4, $q$Аннуитетный платёж$q$, $q$Равный ежемесячный платёж по займу на весь срок: в начале в нём больше процентов, в конце — основного долга.$q$),
  (5, $q$Дифференцированный платёж$q$, $q$Платёж, при котором основной долг гасится равными долями, а проценты начисляются на остаток — платежи уменьшаются со временем.$q$),
  (6, $q$ГЭСВ$q$, $q$Годовая эффективная ставка вознаграждения — реальная стоимость займа с учётом всех комиссий и платежей.$q$),
  (7, $q$ДДУ$q$, $q$Договор о долевом участии в жилищном строительстве: дольщик финансирует строительство и получает квартиру после ввода дома.$q$),
  (8, $q$Обременение$q$, $q$Ограничение права собственности: залог, арест, аренда, доверительное управление и т.п. Отражается в справке о зарегистрированных правах.$q$),
  (9, $q$Арест$q$, $q$Запрет распоряжаться имуществом, наложенный судом или судебным исполнителем.$q$),
  (10, $q$Правоустанавливающий документ$q$, $q$Документ, на основании которого возникло право: договор купли-продажи, дарения, свидетельство о наследстве, решение суда.$q$),
  (11, $q$Технический паспорт$q$, $q$Документ с характеристиками объекта: адрес, кадастровый номер, год и материал постройки, площади, поэтажный план.$q$),
  (12, $q$Кадастровый номер$q$, $q$Уникальный номер объекта недвижимости или земельного участка в государственном кадастре.$q$),
  (13, $q$Идентификационный документ на земельный участок$q$, $q$Документ с кадастровым номером, площадью, целевым назначением и планом участка.$q$),
  (14, $q$Государственная регистрация прав$q$, $q$Внесение сведений о праве в государственный реестр. Право собственности на недвижимость возникает с момента регистрации.$q$),
  (15, $q$ЦОН$q$, $q$Центр обслуживания населения (НАО «Правительство для граждан»): регистрация сделок, выдача техпаспортов и справок.$q$),
  (16, $q$eGov$q$, $q$Портал электронного правительства: справки, регистрация прав и сделок онлайн с ЭЦП.$q$),
  (17, $q$ЭЦП$q$, $q$Электронная цифровая подпись для подписания документов и получения госуслуг онлайн.$q$),
  (18, $q$МРП$q$, $q$Месячный расчётный показатель; в 2026 году — 4 325 ₸. Через МРП считаются пошлины, тарифы нотариусов, пороги налогов.$q$),
  (19, $q$ИПН$q$, $q$Индивидуальный подоходный налог. При продаже недвижимости уплачивается с прироста стоимости, если не выдержан минимальный срок владения.$q$),
  (20, $q$Форма 270.00$q$, $q$Декларация о доходах и имуществе физического лица, в том числе для доходов от продажи имущества.$q$),
  (21, $q$Рыночная стоимость$q$, $q$Наиболее вероятная цена, по которой объект может быть продан на открытом рынке между независимыми сторонами.$q$),
  (22, $q$Ликвидационная стоимость$q$, $q$Цена при вынужденной сжатой по срокам продаже, обычно ниже рыночной.$q$),
  (23, $q$Инвестиционная стоимость$q$, $q$Стоимость для конкретного инвестора с учётом его целей и требуемой доходности.$q$),
  (24, $q$Сравнительный подход$q$, $q$Определение стоимости по ценам сделок и предложений с аналогичными объектами с поправками на отличия.$q$),
  (25, $q$Доходный подход$q$, $q$Определение стоимости через будущие доходы объекта: капитализация или дисконтирование денежных потоков.$q$),
  (26, $q$Затратный подход$q$, $q$Стоимость создания аналогичного объекта за вычетом износа плюс стоимость земли.$q$),
  (27, $q$Отчёт об оценке$q$, $q$Документ с описанием объекта, целей, допущений, расчётов и итоговой стоимости, подписанный оценщиком.$q$),
  (28, $q$Палата оценщиков$q$, $q$Саморегулируемая организация оценщиков; членство и квалификационное свидетельство — условие работы оценщика.$q$),
  (29, $q$Хоумстейджинг$q$, $q$Предпродажная подготовка жилья: расхламление, мелкий ремонт, декор и свет под съёмку и показы.$q$),
  (30, $q$Эксклюзивный договор$q$, $q$Договор, по которому собственник поручает продажу или аренду только одному агентству.$q$),
  (31, $q$Первичный рынок$q$, $q$Продажа жилья от застройщика: новостройки и строящиеся дома.$q$),
  (32, $q$Вторичный рынок$q$, $q$Продажа жилья, право собственности на которое уже зарегистрировано за физическим или юридическим лицом.$q$),
  (33, $q$ПСН$q$, $q$Помещение свободного назначения: можно использовать под офис, магазин, услуги.$q$),
  (34, $q$ОСИ$q$, $q$Объединение собственников имущества многоквартирного дома — форма управления домом, пришедшая на смену КСК.$q$),
  (35, $q$Депозит нотариуса$q$, $q$Приём нотариусом денег для передачи продавцу после выполнения условий сделки.$q$),
  (36, $q$Аккредитив$q$, $q$Банковский способ расчёта: деньги покупателя блокируются в банке и перечисляются продавцу после регистрации права.$q$),
  (37, $q$Доверительное управление$q$, $q$Передача управления объектом (например, арендой) профессиональному управляющему по договору.$q$),
  (38, $q$Ставка капитализации$q$, $q$Отношение годового чистого дохода объекта к его стоимости; используется в доходном подходе.$q$),
  (39, $q$Окупаемость$q$, $q$Срок, за который доход от объекта покрывает вложения в его покупку.$q$)
insert into public.mortgage_programs (id, name, bank, rate, rate_text, down_payment_pct, term_years, max_amount, max_amount_text, housing, who, notes, url, sort, checked_at, is_active) values
  (1, $q$Наурыз$q$, $q$Отбасы банк$q$, 9, $q$9%; 7% — для социально уязвимых категорий$q$, 10, 19, 36000000, $q$до 36 млн ₸ в Астане и Алматы, до 30 млн ₸ в регионах (лимиты пересматриваются)$q$, $q$Первичное жильё с чистовой отделкой — взнос от 10%; черновая отделка и вторичка — от 20%$q$, $q$Граждане РК, у которых и у членов семьи нет жилья в собственности последние 5 лет. При отборе учитываются баллы по депозиту в Отбасы банке.$q$, $q$Приём заявок проходит волнами; в 2026 году участники списка подавали заявки весной. Программа будет работать минимум до 2031 года.$q$, $q$https://hcsbk.kz$q$, 1, $q$2026-10-25$q$, true),
  (2, $q$Наурыз жұмыскер$q$, $q$Отбасы банк$q$, 9, $q$7–9%$q$, 10, 19, 36000000, $q$до 36 млн ₸ в Астане и Алматы, до 30 млн ₸ в регионах$q$, $q$Первичное жильё; вторичное — в моногородах и сёлах при соблюдении требований$q$, $q$Работники промышленности, энергетики, транспорта, сельского и водного хозяйства$q$, $q$$q$, $q$https://hcsbk.kz$q$, 2, $q$2026-10-25$q$, true),
  (3, $q$Наурыз Әскери$q$, $q$Отбасы банк$q$, 9, $q$9%$q$, 0, 19, 80000000, $q$до 30–36 млн ₸ при взносе до 20%; до 80 млн ₸ при взносе 20–50%$q$, $q$Введённое в эксплуатацию первичное жильё$q$, $q$Военнослужащие и получатели жилищных выплат$q$, $q$Взнос от 0% до 50%.$q$, $q$https://hcsbk.kz$q$, 3, $q$2026-10-25$q$, true),
  (4, $q$Отау$q$, $q$Отбасы банк$q$, 9, $q$7–9%; после накопления 50% суммы займа — 3,5–5%$q$, 20, 19, 36000000, $q$до 36 млн ₸$q$, $q$По условиям программы$q$, $q$Вкладчики Отбасы банка$q$, $q$$q$, $q$https://hcsbk.kz$q$, 4, $q$2026-10-25$q$, true),
  (5, $q$Свой дом$q$, $q$Отбасы банк$q$, 7, $q$от 7% (предварительный заём), 3,5–5% после накопления 50%$q$, 20, 25, null, $q$по условиям программы$q$, $q$Строительство индивидуального жилого дома$q$, $q$Вкладчики Отбасы банка с депозитом не менее 500 000 ₸ на момент заявления$q$, $q$$q$, $q$https://hcsbk.kz$q$, 5, $q$2026-10-25$q$, true),
